// Package texsample provides mipmapped texture sampling for a software
// rasterizer.
//
// Mipmaps are generated by box averaging in linear-light space. Non power of
// two (including odd) dimensions are handled by a weighted 2x2 box filter that
// averages the actual texels covered at each level. Sampling supports nearest,
// bilinear and trilinear filtering, LOD computed from screen-space derivatives,
// repeat/mirror/clamp address modes, and sRGB textures whose texels are
// decoded to linear space before any interpolation.
package texsample

// WrapMode selects how texture coordinates outside [0, 1) are addressed.
type WrapMode int

const (
	WrapRepeat WrapMode = iota
	WrapMirror
	WrapClamp
)

// Filter selects the magnification/minification filter used by a Sampler.
type Filter int

const (
	// FilterNearest picks a single texel (and a single mip level).
	FilterNearest Filter = iota
	// FilterBilinear interpolates four texels within a single mip level.
	FilterBilinear
	// FilterTrilinear bilinearly interpolates two adjacent mip levels and
	// blends between them according to the fractional LOD.
	FilterTrilinear
)

// Level stores one mip level as interleaved RGBA float32 values in linear
// space. A texel (x, y) starts at index (y*W+x)*4.
type Level struct {
	Data []float32
	W, H int
}

// Texture is a mipmapped RGBA texture whose levels are stored in linear
// space. Level 0 always holds the decoded source image.
type Texture struct {
	Levels []Level
	SRGB   bool
}

// MaxLOD returns the index of the smallest mip level (floor(log2(max(w,h)))).
func (t *Texture) MaxLOD() int {
	return len(t.Levels) - 1
}

// MipDimensions reports the dimensions of level l for a base image of size
// (w, h). Each dimension is halved and rounded up until it reaches 1, so odd
// dimensions shrink as n -> ceil(n/2) (e.g. 5 -> 3 -> 2 -> 1).
func MipDimensions(w, h, l int) (lw, lh int) {
	lw, lh = w, h
	for i := 0; i < l; i++ {
		lw = (lw + 1) / 2
		lh = (lh + 1) / 2
	}
	return lw, lh
}

// MipLevelCount returns the number of mip levels generated for the given base
// dimensions, including level 0.
func MipLevelCount(w, h int) int {
	n := w
	if h > n {
		n = h
	}
	count := 1
	for n > 1 {
		n = (n + 1) / 2
		count++
	}
	return count
}
